    SET @NC = (SELECT COUNT(*) FROM #C WHERE TName = N'MemOutStation');

    IF @NC = 0
        PRINT 'SKIPPED [MemOutStation] -> source table missing';
    ELSE IF OBJECT_ID(N'dbo.[MemOutStation]', N'U') IS NULL
        PRINT 'SKIPPED [MemOutStation] -> destination table missing';
    ELSE IF EXISTS (SELECT 1 FROM #C WHERE TName = N'MemOutStation'
                    AND CName NOT IN (SELECT name FROM sys.columns
                                      WHERE object_id = OBJECT_ID(N'dbo.[MemOutStation]')))
        PRINT 'SKIPPED [MemOutStation] -> source ke kuch columns destination me nahi hain';
    ELSE IF EXISTS (SELECT 1 FROM sys.columns
                    WHERE object_id = OBJECT_ID(N'dbo.[MemOutStation]')
                      AND name NOT IN (SELECT CName FROM #C WHERE TName = N'MemOutStation'))
        PRINT 'SKIPPED [MemOutStation] -> destination me extra columns hain'
    ELSE
    BEGIN
        BEGIN TRY
            PRINT 'Transferring [MemOutStation] ...';

            IF OBJECT_ID(N'tempdb..#S_T', N'U') IS NOT NULL DROP TABLE #S_T;

            -- (1) source data ek baar local staging me (single read)
            SELECT IDENTITY(int, 1, 1) AS _xf_rid, [Code], [Type], [MemCode], [FrDate], [ToDate], [RevenueChng], [FrMonth], [ToMonth], [Site_Code], [LogSite_Code], [U_AE], [U_EntDt], [U_Name]
            INTO #S_T
            FROM OPENQUERY([SRC], N'SELECT [Code],[Type],[MemCode],[FrDate],[ToDate],[RevenueChng],[FrMonth],[ToMonth],[Site_Code],[LogSite_Code],[U_AE],[U_EntDt],[U_Name] FROM [VijayData2627].dbo.[MemOutStation]') AS s;

            CREATE CLUSTERED INDEX _xf_ix ON #S_T (_xf_rid);

            SET @MaxRid = ISNULL((SELECT MAX(_xf_rid) FROM #S_T), 0);
            SET @lo = 1; SET @hi = 0; SET @BN = 0; SET @Tot = 0;

            -- (2) batch-wise copy: har batch apne transaction me (@B rows)
            WHILE @lo <= @MaxRid
            BEGIN
                SET @hi = @lo + @B - 1;
                BEGIN TRANSACTION;
                    INSERT INTO [dbo].[MemOutStation] ([Code], [Type], [MemCode], [FrDate], [ToDate], [RevenueChng], [FrMonth], [ToMonth], [Site_Code], [LogSite_Code], [U_AE], [U_EntDt], [U_Name])
                    SELECT [Code], [Type], [MemCode], [FrDate], [ToDate], [RevenueChng], [FrMonth], [ToMonth], [Site_Code], [LogSite_Code], [U_AE], [U_EntDt], [U_Name]
                    FROM #S_T AS st
                    WHERE st._xf_rid >= @lo AND st._xf_rid <= @hi
                       AND NOT EXISTS (SELECT 1 FROM [dbo].[MemOutStation] AS d
                                        WHERE d.[Code] = st.[Code] COLLATE DATABASE_DEFAULT)
                    SET @RC = @@ROWCOUNT;
                    COMMIT TRANSACTION;

                    SET @Tot = @Tot + @RC;
                IF @RC > 0
                BEGIN
                    SET @BN = @BN + 1;
                    PRINT '   batch ' + CAST(@BN AS varchar(10)) + ': '
                          + CAST(@RC AS varchar(20)) + ' rows (total '
                          + CAST(@Tot AS varchar(20)) + ')';
                END
                SET @lo = @hi + 1;
            END

            PRINT '   DONE [MemOutStation]: ' + CAST(@Tot AS varchar(20)) + ' rows, '
                  + CAST(@BN AS varchar(10)) + ' batch(es)';

            DROP TABLE #S_T;
        END TRY
        BEGIN CATCH
            IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
            IF OBJECT_ID(N'tempdb..#S_T', N'U') IS NOT NULL DROP TABLE #S_T;
            PRINT '   FAILED [MemOutStation] -> ' + ERROR_MESSAGE();
        END CATCH;
    END
END

