IF @OK = 1
BEGIN
    SET @NC = (SELECT COUNT(*) FROM #C WHERE TName = N'Employee');

    IF @NC = 0
        PRINT 'SKIPPED [Employee] -> source table missing';
    ELSE IF OBJECT_ID(N'dbo.[Employee]', N'U') IS NULL
        PRINT 'SKIPPED [Employee] -> destination table missing';
    ELSE IF EXISTS (SELECT 1 FROM #C WHERE TName = N'Employee'
                    AND CName NOT IN (SELECT name FROM sys.columns
                                      WHERE object_id = OBJECT_ID(N'dbo.[Employee]')))
        PRINT 'SKIPPED [Employee] -> source ke kuch columns destination me nahi hain';
    ELSE IF EXISTS (SELECT 1 FROM sys.columns
                    WHERE object_id = OBJECT_ID(N'dbo.[Employee]')
                      AND name NOT IN (SELECT CName FROM #C WHERE TName = N'Employee'))
