IF @OK = 1
BEGIN
    SET @NC = (SELECT COUNT(*) FROM #C WHERE TName = N'DispColor');

    IF @NC = 0
        PRINT 'SKIPPED [DispColor] -> source table missing';
    ELSE IF OBJECT_ID(N'dbo.[DispColor]', N'U') IS NULL
        PRINT 'SKIPPED [DispColor] -> destination table missing';
    ELSE IF EXISTS (SELECT 1 FROM #C WHERE TName = N'DispColor'
                    AND CName NOT IN (SELECT name FROM sys.columns
                                      WHERE object_id = OBJECT_ID(N'dbo.[DispColor]')))
        PRINT 'SKIPPED [DispColor] -> source ke kuch columns destination me nahi hain';
    ELSE IF EXISTS (SELECT 1 FROM sys.columns
                    WHERE object_id = OBJECT_ID(N'dbo.[DispColor]')
                      AND name NOT IN (SELECT CName FROM #C WHERE TName = N'DispColor'))
        PRINT 'SKIPPED [DispColor] -> destination me extra columns hain'
    ELSE
    BEGIN
        BEGIN TRY
            PRINT 'Transferring [DispColor] ...';

            IF OBJECT_ID(N'tempdb..#S_T', N'U') IS NOT NULL DROP TABLE #S_T;

            -- (1) source data ek baar local staging me (single read)
