            INTO #S_T
            FROM OPENQUERY([SRC], N'SELECT [Index],[Color],[Detail],[Site_Code],[U_Name],[U_EntDt],[U_AE],[LogSite_Code] FROM [VijayData2627].dbo.[DispColor]') AS s;

