                                        WHERE d.[Index] = st.[Index] AND d.[LogSite_Code] = st.[LogSite_Code] COLLATE DATABASE_DEFAULT)
                    SET @RC = @@ROWCOUNT;
                    COMMIT TRANSACTION;

                    SET @Tot = @Tot + @RC;
                IF @RC > 0
